<?php $me=current_user(); $myBookings=array_values(array_filter($data['bookings'],fn($b)=>(int)$b['passenger_id']===(int)$me['id'])); $driverBookings=array_values(array_filter($data['bookings'],fn($b)=>(int)$b['driver_id']===(int)$me['id'])); ?>
<section class="page-heading dashboard-heading"><div><p class="eyebrow">YOUR MAPIDO</p><h1>Good day, <?= e(explode(' ',$me['name'])[0]) ?>.</h1><p>Here’s what’s moving.</p></div><div class="heading-actions"><a href="index.php?page=find" class="btn btn-outline-dark">Find a ride</a><?php if($me['role']==='driver'): ?><a href="index.php?page=offer" class="btn btn-primary">Offer a ride <span aria-hidden="true">↗</span></a><?php endif; ?></div></section>
<section class="dashboard-grid"><div class="dashboard-main"><div class="section-head"><h2><?= $me['role']==='driver'?'Ride requests':'Your bookings' ?></h2><a href="index.php?page=bookings">View history →</a></div>
<?php $rows=$me['role']==='driver'?$driverBookings:$myBookings; if(!$rows): ?><div class="empty-state compact"><span class="empty-icon">↗</span><h3>No journeys on the board.</h3><p><?= $me['role']==='driver'?'Publish a ride to start receiving seat requests.':'Search for a route and request your first seat.' ?></p><a class="btn btn-outline-dark" href="index.php?page=<?= $me['role']==='driver'?'offer':'find' ?>"><?= $me['role']==='driver'?'Offer a ride':'Find a ride' ?></a></div><?php endif; ?>
<?php foreach($rows as $booking): ?><article class="booking-row"><div class="booking-route"><strong><?= e($booking['origin']) ?> <span>→</span> <?= e($booking['destination']) ?></strong><small><?= e(date('D, M j',strtotime($booking['travel_date']))) ?> · <?= e(substr($booking['departure_time'],0,5)) ?> · <?= (int)$booking['seats'] ?> seat<?= $booking['seats']>1?'s':'' ?></small></div><span class="status status-<?= strtolower($booking['status']) ?>"><?= e($booking['status']) ?></span><?php if($me['role']==='driver' && $booking['status']==='Pending'): ?><div class="row-actions"><form method="post"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="booking_status"><input type="hidden" name="return_page" value="dashboard"><input type="hidden" name="booking_id" value="<?= (int)$booking['id'] ?>"><input type="hidden" name="status" value="Confirmed"><button class="btn btn-primary btn-sm">Accept</button></form><form method="post"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="booking_status"><input type="hidden" name="return_page" value="dashboard"><input type="hidden" name="booking_id" value="<?= (int)$booking['id'] ?>"><input type="hidden" name="status" value="Rejected"><button class="btn btn-link btn-sm text-danger">Decline</button></form></div><?php elseif($me['role']==='driver'): ?><span class="small muted">Passenger: <?= e($booking['passenger_name']) ?></span><?php else: ?><span class="small muted">Driver: <?= e($booking['driver_name']) ?></span><?php endif; ?></article><?php endforeach; ?>
</div><aside class="dashboard-side"><div class="side-title"><h2>Recent updates</h2><span class="live-mark"></span></div><?php if(empty($data['notifications'])): ?><p class="muted side-empty">Your booking updates will appear here.</p><?php else: foreach($data['notifications'] as $notification): ?><div class="notification-row"><span class="notification-dot"></span><span><?= e($notification['message']) ?><small><?= e(date('M j · g:i a',strtotime($notification['created_at']))) ?></small></span></div><?php endforeach; endif; ?><a class="support-link" href="index.php?page=support">Need help with a journey? →</a></aside></section>
<?php if($me['role']==='driver'): ?><section class="offered-rides"><div class="section-head"><h2>Rides you’ve offered</h2><a href="index.php?page=offer">+ New ride</a></div><?php if(!$data['rides']): ?><p class="muted">Your published routes will appear here.</p><?php endif; ?><?php foreach($data['rides'] as $ride): ?><article class="offered-row"><div><strong><?= e($ride['origin']) ?> <span>→</span> <?= e($ride['destination']) ?></strong><small><?= e(date('D, M j',strtotime($ride['travel_date']))) ?> · <?= e(substr($ride['departure_time'],0,5)) ?> · <?= (int)$ride['seats_left'] ?> open seats</small></div><span class="status status-<?= strtolower($ride['status']) ?>"><?= e($ride['status']) ?></span><div class="row-actions"><?php if($ride['status']==='Open'): ?><details class="edit-ride-details"><summary>Edit</summary><form method="post" class="edit-ride-form"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="update_ride"><input type="hidden" name="return_page" value="dashboard"><input type="hidden" name="ride_id" value="<?= (int)$ride['id'] ?>"><label class="form-label">Origin<input class="form-control" name="origin" required maxlength="100" value="<?= e($ride['origin']) ?>"></label><label class="form-label">Destination<input class="form-control" name="destination" required maxlength="100" value="<?= e($ride['destination']) ?>"></label><label class="form-label">Date<input class="form-control" name="travel_date" type="date" min="<?= e(date('Y-m-d')) ?>" required value="<?= e($ride['travel_date']) ?>"></label><label class="form-label">Departure<input class="form-control" name="departure_time" type="time" required value="<?= e(substr($ride['departure_time'],0,5)) ?>"></label><label class="form-label">Total seats<input class="form-control" name="seats" type="number" min="1" max="8" required value="<?= (int)$ride['total_seats'] ?>"></label><label class="form-label">Estimated journey cost<input class="form-control" name="estimated_cost" type="number" min="0" step="50" required value="<?= e($ride['estimated_cost']) ?>"></label><label class="form-label">Travel notes<input class="form-control" name="notes" maxlength="1000" value="<?= e($ride['notes']) ?>"></label><label class="form-label">Pickup points<textarea class="form-control" name="pickup_points" maxlength="600" rows="2"><?= e($ride['pickup_points']??'') ?></textarea></label><button class="btn btn-primary btn-sm">Save changes</button></form></details><?php if($ride['travel_date']<=date('Y-m-d')): ?><form method="post"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="complete_ride"><input type="hidden" name="return_page" value="dashboard"><input type="hidden" name="ride_id" value="<?= (int)$ride['id'] ?>"><button class="btn btn-outline-dark btn-sm">Complete</button></form><?php endif; ?><form method="post" data-confirm="Cancel this ride and notify all booked passengers?"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="cancel_ride"><input type="hidden" name="return_page" value="dashboard"><input type="hidden" name="ride_id" value="<?= (int)$ride['id'] ?>"><button class="btn btn-link btn-sm text-danger">Cancel ride</button></form><?php endif; ?></div></article><?php endforeach; ?></section><?php endif; ?>